extracted_python_code:
customer_success_rates = Customers.WHERE(
    COUNT(transactions_made) >= 5
).CALCULATE(
    customer_name=name,
    successful_transactions=COUNT(transactions_made.WHERE(LOWER(status) == 'success')),
    total_transactions=COUNT(transactions_made)
).CALCULATE(
    customer_name=customer_name,
    success_rate=100.0 * successful_transactions / total_transactions
).ORDER_BY(success_rate.ASC())

result = Broker.CALCULATE(
    num_customers=COUNT(
        Customers.WHERE(
            ENDSWITH(email, '.com') & 
            HAS(
                transactions_made.WHERE(
                    CONTAINS(ticker.symbol, 'AMZN') |
                    CONTAINS(ticker.symbol, 'AAPL') |
                    CONTAINS(ticker.symbol, 'GOOGL') |
                    CONTAINS(ticker.symbol, 'META') |
                    CONTAINS(ticker.symbol, 'NFLX')
                )
            ) == 1
        )
    )
)

tac_by_country = Customers.WHERE(
    (LOWER(status) == 'active') & (join_date >= '2023-01-01')
).PARTITION(
    name='country_groups', by=(country)
).CALCULATE(
    country=country,
    tac_count=COUNT(Customers)
)

top_bought_tickers = Transactions.WHERE(
    (DATEDIFF("days", date_time, DATETIME('now')) <= 10) & (LOWER(transaction_type) == 'buy')
).CALCULATE(
    ticker_symbol=ticker.symbol
).PARTITION(
    name="ticker_groups", by=(ticker_symbol)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    num_buy_transactions=COUNT(Transactions)
).TOP_K(2, by=num_buy_transactions.DESC())

recent_customers_by_month = Customers.WHERE(
    (DATEDIFF("months", join_date, DATETIME('now')) > 0) & (DATEDIFF("months", join_date, DATETIME('now')) <= 6)
).CALCULATE(
    signup_month=JOIN_STRINGS("-", YEAR(join_date), LPAD(MONTH(join_date), 2, "0"))
)

result = recent_customers_by_month.PARTITION(name="monthly_groups", by=(signup_month)).CALCULATE(
    month=signup_month,
    PMCS=COUNT(Customers),
    PMAT=AVG(Customers.transactions_made.amount)
).ORDER_BY(signup_month.ASC())

acp_by_type = DailyPrices.WHERE(
    DATEDIFF("days", date, DATETIME('now')) <= 6
).CALCULATE(
    type_of_ticker=ticker.ticker_type
).PARTITION(
    name="type_groups", by=(type_of_ticker,)
).CALCULATE(
    ticker_type=type_of_ticker,
    average_closing_price=AVG(DailyPrices.close)
)

result = Broker.CALCULATE(
    num_customers=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

filtered_transactions = Transactions.WHERE(
    (date_time >= "2023-01-01") & (date_time < "2023-04-01")
)

transaction_summary = filtered_transactions.PARTITION(
    name="transaction_groups", by=transaction_type
).CALCULATE(
    transaction_type=transaction_type,
    num_distinct_customers=NDISTINCT(Transactions.customer_id),
    avg_shares=AVG(Transactions.shares)
)

top_transaction_types = transaction_summary.TOP_K(
    3, by=num_distinct_customers.DESC()
)

buy_customers = Transactions.WHERE(LOWER(transaction_type) == 'buy').PARTITION(name="distinct_customers", by=(customer_id)).CALCULATE(
    customer_id=customer_id
)

distinct_ticker_ids = DailyPrices.WHERE(date >= '2023-04-01').PARTITION(name="distinct_tickers", by=ticker_id).CALCULATE(
    ticker_id=ticker_id
)

result = Transactions.WHERE(
    DATEDIFF("days", date_time, 'now') <= 30
).CALCULATE(
    country_name=customer.country
).PARTITION(
    name="countries", by=(country_name)
).CALCULATE(
    country=country_name,
    num_transactions=COUNT(Transactions),
    total_transaction_amount=SUM(Transactions.amount)
).TOP_K(5, by=total_transaction_amount.DESC())

result = Broker.CALCULATE(
    lowest_close_price=MIN(
        DailyPrices.WHERE(
            (ticker.symbol == 'VTI') & 
            (DATEDIFF("days", date, DATETIME('now')) <= 7)
        ).close
    )
)

result = Broker.CALCULATE(
    num_transactions=COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, DATETIME("now")) <= 70
        ).transactions_made
    )
)

top_customer_by_transactions = Customers.CALCULATE(
    _id,
    name,
    num_transactions=COUNT(transactions_made.WHERE(
        (LOWER(transaction_type) == 'sell') & 
        (DATEDIFF("days", date_time, "2023-04-01") == 0)
    ))
).WHERE(
    num_transactions > 0
).TOP_K(
    1, 
    by=num_transactions.DESC()
)

asp_q1_2023 = Dealership.CALCULATE(
    asp_q1_2023=AVG(Sales.WHERE((YEAR(sale_date) == 2023) & (MONTH(sale_date) <= 3)).sale_price)
)

gpm_2023 = Dealership.CALCULATE(
    total_revenue_2023=SUM(Sales.WHERE(YEAR(sale_date) == 2023).sale_price),
    total_cost_2023=SUM(Sales.WHERE(YEAR(sale_date) == 2023).car.cost)
).CALCULATE(
    gpm=(total_revenue_2023 - total_cost_2023) / total_cost_2023 * 100.0
)

total_sales_count = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, 'now') < 7))
)

distinct_customer_ids = Sales.PARTITION(name="customer_sales", by=(customer_id)).CALCULATE(
    customer_id=customer_id
)

salesperson_ids_with_cash_payment = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(LOWER(payment_method) == 'cash')) == 1
).CALCULATE(
    salesperson_id=_id
)

weekend_payments_to_utility_co = Dealership.CALCULATE(
    num_weekend_payments=COUNT(
        PaymentsMade.WHERE(
            (LOWER(vendor_name) == 'utility company') & 
            ISIN(DAYNAME(payment_date), ('Saturday', 'Sunday'))
        )
    )
)

result = Drugs.CALCULATE(
    drug_name=drug_name,
    average_ddd=AVG(
        treatments_used_in.WHERE(
            PRESENT(end_dt) & (DATEDIFF("days", start_dt, end_dt) > 0)
        ).CALCULATE(
            ddd_value=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd_value
    )
)

gmail_or_yahoo_patients_count = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            ENDSWITH(LOWER(email), '@gmail.com') | ENDSWITH(LOWER(email), '@yahoo.com')
        )
    )
)

result = DermTreatment.CALCULATE(
    patient_count=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (LOWER(diagnosis.diag_name) == LOWER('Psoriasis vulgaris')) &
                    (LOWER(drug.drug_type) == LOWER('Biologic'))
                )
            ) == 1
        )
    )
)

result = DermTreatment.CALCULATE(
    start_of_current_month=DATETIME('now', 'start of month'),
    start_of_12_months_ago=DATETIME('now', 'start of month', '-12 months')
).Treatments.WHERE(
    (start_dt >= start_of_12_months_ago) & (start_dt < start_of_current_month)
).CALCULATE(
    treatment_month=DATETIME(start_dt, 'start of month')
).PARTITION(
    name="monthly_groups", by=(treatment_month)
).CALCULATE(
    month=treatment_month,
    PMPD=NDISTINCT(Treatments.patient_id),
    PMTC=COUNT(Treatments)
).ORDER_BY(month.ASC())

result = DermTreatment.CALCULATE(
    avg_weight=AVG(Drugs.WHERE(LOWER(drug_name) == 'drugalin').treatments_used_in.patient.weight_kg)
)

caw_male_patients = DermTreatment.CALCULATE(
    caw=AVG(Patients.WHERE(LOWER(gender) == 'male').weight_kg)
)

result = DermTreatment.CALCULATE(
    PIC=COUNT(Patients.WHERE((LOWER(gender) == 'female') & (LOWER(ins_type) == 'private')))
)

result = Drugs.CALCULATE(
    drug_id=drug_id,
    drug_name=drug_name,
    num_adverse_events=COUNT(
        treatments_used_in.adverse_events.WHERE(
            (YEAR(reported_dt) == YEAR(treatment.start_dt)) &
            (MONTH(reported_dt) == MONTH(treatment.start_dt))
        )
    )
).TOP_K(1, by=num_adverse_events.DESC())

biologic_doctor_states = Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(LOWER(drug.drug_type) == 'biologic')) == 1
).PARTITION(
    name="states", by=(loc_state)
).CALCULATE(
    state=loc_state
)

insurance_type_performance = DermTreatment.Treatments.WHERE(
    YEAR(end_dt) == 2022
).CALCULATE(
    insurance_type=patient.ins_type
).PARTITION(
    name="insurance_groups", by=insurance_type
).CALCULATE(
    ins_type=insurance_type,
    avg_pasi_score_100=AVG(Treatments.outcome_records.day100_pasi_score),
    num_distinct_patients=NDISTINCT(Treatments.patient.patient_id)
).TOP_K(5, by=avg_pasi_score_100.ASC())

top_diagnoses_by_itch_score = Diagnoses.WHERE(
    HAS(treatments_for.outcome_records) == 1
).CALCULATE(
    diagnosis_name=diag_name,
    max_itch_score=MAX(treatments_for.outcome_records.day100_itch_vas),
    num_patients=NDISTINCT(treatments_for.patient.patient_id)
).TOP_K(
    3,
    by=(max_itch_score.DESC(), num_patients.DESC())
)

recent_psoriasis_treatments = DermTreatment.CALCULATE(
    treatment_count=COUNT(
        Treatments.WHERE(
            (LIKE(LOWER(diagnosis.diag_name), '%psoriasis%')) &
            (PRESENT(drug.fda_appr_dt)) &
            (PRESENT(end_dt)) &
            (DATEDIFF("months", end_dt, DATETIME('now')) <= 6)
        )
    )
)

result = Patients.WHERE(
    (LOWER(gender) == 'male') & 
    (LOWER(ins_type) == 'private')
).CALCULATE(
    age_in_years = DATEDIFF("years", date_of_birth, DATETIME('now'))
).CALCULATE(
    average_age = AVG(age_in_years)
)

result = Merchants.CALCULATE(
    merchant_name=name,
    cpur=NDISTINCT(
        transactions_received.WHERE(
            LOWER(status) == LOWER('successful')
        ).WHERE(
            coupon_id != None
        ).coupon_id
    ) / NDISTINCT(
        transactions_received.WHERE(
            LOWER(status) == LOWER('successful')
        ).txid
    )
)

result = Ewallet.CALCULATE(
    num_transactions=COUNT(
        Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME('now')) <= 7
        )
    ),
    total_amount=SUM(
        Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME('now')) <= 7
        ).amount
    )
)

lub_per_user = Users.CALCULATE(
    user_id=uid,
    latest_user_balance=balances.WHERE(
        RANKING(by=updated_at.DESC(), per="Users") == 1
    ).SINGULAR().balance
)

user_marketing_preference = Ewallet.Users.CALCULATE(
    user_id=uid,
    marketing_opt_in=setting_snapshots.WHERE(
        RANKING(by=snapshot_date.DESC(), per="Users") == 1
    ).SINGULAR().marketing_opt_in
)

user_session_durations = Users.CALCULATE(
    user_id=uid,
    total_duration=ROUND(SUM(
        sessions.WHERE(
            (session_start_ts >= '2023-06-01') & (session_start_ts < '2023-06-08')
        ).CALCULATE(
            duration_in_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration_in_seconds
    ), 0)
).WHERE(
    total_duration > 0
).ORDER_BY(
    total_duration.DESC()
)

result = Ewallet.CALCULATE(
    total_user_sessions=COUNT(
        UserSessions.WHERE(
            DATEDIFF("days", session_start_ts, DATETIME("now")) <= 30
        )
    )
)

result = Ewallet.Merchants.CALCULATE(
    merchant_creation_year=YEAR(created_at),
    merchant_creation_month=MONTH(created_at)
).CALCULATE(
    merchant_id=mid,
    merchant_name=name,
    num_coupons=COUNT(
        coupons.WHERE(
            (YEAR(created_at) == merchant_creation_year) & (MONTH(created_at) == merchant_creation_month)
        )
    )
).TOP_K(1, by=num_coupons.DESC())

distinct_transaction_notification_users = Notifications.WHERE(
    LOWER(notification_type) == 'transaction'
).PARTITION(
    name='distinct_users', by=user_id
).CALCULATE(
    user_id
)

top_countries_by_amount_sent = Ewallet.Transactions.WHERE(sender_type == 0).CALCULATE(
    sender_country=sending_user.country
).PARTITION(
    name="countries", by=(sender_country)
).CALCULATE(
    country=sender_country,
    total_transaction_amount=SUM(Transactions.amount),
    num_distinct_users=NDISTINCT(Transactions.sender_id)
).TOP_K(5, by=total_transaction_amount.DESC())

# Filter for active merchants whose category contains 'retail'
active_retail_merchants = Merchants.WHERE(
    (LOWER(status) == 'active') & 
    (CONTAINS(LOWER(category), 'retail'))
)

# Get today's balances for these merchants and calculate the median
result = Ewallet.CALCULATE(
    median_balance=MEDIAN(
        active_retail_merchants.balances.WHERE(
            DATEDIFF("days", updated_at, DATETIME('now')) == 0
        ).balance
    )
)

# Find the earliest snapshot date in 2023
earliest_2023_snapshot = UserSettingSnapshots.WHERE(
    YEAR(snapshot_date) == 2023
).TOP_K(1, by=snapshot_date.ASC())

# Calculate the average limits for that earliest date
result = Ewallet.CALCULATE(
    avg_daily_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_2023_snapshot.SINGULAR().snapshot_date
        ).tx_limit_daily
    ),
    avg_monthly_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_2023_snapshot.SINGULAR().snapshot_date
        ).tx_limit_monthly
    )
)

average_session_duration_by_device = UserSessions.PARTITION(
    name="sessions_by_device", by=(device_type)
).CALCULATE(
    device_type=device_type,
    average_duration_seconds=AVG(
        UserSessions.CALCULATE(
            duration=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration
    )
)

result = Users.WHERE(
    HASNOT(
        notifications.WHERE(
            DATEDIFF("days", user.created_at, created_at) <= 365
        )
    ) == 1
).CALCULATE(
    user_name=username,
    user_email=email,
    signup_date=created_at
)
